import org.testcontainers.utility.DockerImageName;
import tools.jackson.databind.json.JsonMapper;
import static org.assertj.core.api.Assertions.*;

/** Actual PostgreSQL/Flyway/crypto authority tests; peer intentionally isolates authority races. */
@Testcontainers @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class RestRegistryIT {
 @Container static final PostgreSQLContainer pg=new PostgreSQLContainer(DockerImageName.parse("postgres:17.11-bookworm@sha256:2cd2c0f809604aaeff6f0ec8f40aecbd025613107561015c69369a1a7f1d3416").asCompatibleSubstituteFor("postgres"));
 @TempDir Path temp;JdbcTemplate db;DriverManagerDataSource ds;JsonMapper json=new JsonMapper();RestCredentials credentials;RestAssertions assertions;RestRegistry registry;Peer peer;UUID org,other,admin,user,auditor;Path ring;
 @BeforeAll void database(){pg.start();ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());db=new JdbcTemplate(ds);db.execute("CREATE ROLE ecosync_runtime NOLOGIN");Flyway.configure().dataSource(ds).schemas("app").defaultSchema("app").load().migrate();}
 @BeforeEach void setup()throws Exception{org=UUID.randomUUID();other=UUID.randomUUID();admin=UUID.randomUUID();user=UUID.randomUUID();auditor=UUID.randomUUID();db.update("INSERT INTO app.organization(id,slug,display_name) VALUES(?,?,?),(?,?,?)",org,org.toString(),"One",other,other.toString(),"Two");for(var e:Map.of(admin,"INTEGRATION_ADMIN",user,"USER",auditor,"AUDITOR").entrySet()){UUID m=UUID.randomUUID();db.update("INSERT INTO app.app_user(id,login,display_name,password_hash) VALUES(?,?,?,?)",e.getKey(),e.getKey().toString(),"Fixture","not-a-login");db.update("INSERT INTO app.membership VALUES(?,?,?)",org,m,e.getKey());db.update("INSERT INTO app.role_assignment VALUES(?,?,?)",org,m,e.getValue());}ring=temp.resolve(UUID.randomUUID()+".json");byte[] key=new byte[32];new SecureRandom().nextBytes(key);Files.writeString(ring,json.writeValueAsString(Map.of("activeKeyId","v1","keys",Map.of("v1",Base64.getEncoder().encodeToString(key)))));credentials=new RestCredentials(db,json,ring.toString());var kp=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();Path priv=temp.resolve(UUID.randomUUID()+".der"),pub=temp.resolve(UUID.randomUUID()+".der");Files.write(priv,kp.getPrivate().getEncoded());Files.write(pub,kp.getPublic().getEncoded());assertions=new RestAssertions(json,priv.toString(),pub.toString());peer=new Peer();registry=build();}
 RestRegistry build(){return new RestRegistry(db,new TenantDirectory(db),credentials,assertions,peer,new JdbcTransactionManager(ds),"http://supplier:8081|dev","development",262144,64,128,20000);}
 String document(){try{return Files.readString(Path.of("../demo-systems/supplier-api/openapi.json"));}catch(Exception e){throw new IllegalStateException();}}
 RestRegistry.Registration input(String secret){return new RestRegistry.Registration("REST "+UUID.randomUUID(),"http://supplier:8081","BEARER","",secret,document());}
 UUID register(){return(UUID)registry.register(admin,org,input("rest-secret-sentinel-"+UUID.randomUUID())).get("id");}
 UUID operation(UUID id){return db.queryForObject("SELECT id FROM app.rest_operation WHERE organization_id=? AND connector_id=? AND version=(SELECT configuration_version FROM app.rest_connector WHERE organization_id=? AND id=?) AND operation_key='listSuppliers'",UUID.class,org,id,org,id);}
 UUID prepared(UUID id){registry.inspect(admin,org,id);UUID op=operation(id);registry.approve(admin,org,id,op,new RestRegistry.Scope("INTEGRATION_ADMIN",true));registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of(),"TEST");registry.activate(admin,org,id);return op;}
 @Test void importAndInspectionNeverAuthorizeOrContactASource(){UUID id=register(),op=operation(id);registry.inspect(admin,org,id);for(String action:List.of("TEST","INVOKE"))assertThatThrownBy(()->registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of(),action)).isInstanceOf(RestFailure.class);assertThat(peer.calls).isZero();assertThatThrownBy(()->registry.activate(admin,org,id)).isInstanceOf(RestFailure.class);}
 @Test void explicitApprovalTestThenActivationAndRealRevisionBinding(){UUID id=register(),op=prepared(id);assertThat(registry.detail(admin,org,id).get("state")).isEqualTo("ACTIVE");registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of("pageSize",2),"INVOKE");assertThat(peer.calls).isEqualTo(2);registry.revise(admin,org,id,input(""));assertThat(registry.detail(admin,org,id).get("state")).isEqualTo("DRAFT");assertThatThrownBy(()->registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of(),"INVOKE")).isInstanceOf(RestFailure.class);assertThat(db.queryForObject("SELECT count(*) FROM app.rest_configuration WHERE connector_id=?",Integer.class,id)).isEqualTo(2);}
 @Test void tenantAndRoleDenialsCauseZeroGatewayCalls(){UUID id=register(),op=prepared(id);peer.calls=0;assertThatThrownBy(()->registry.register(user,org,input("long-secret-sentinel"))).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->registry.detail(admin,other,id)).isInstanceOf(AccessDeniedException.class);for(UUID actor:List.of(user,auditor))assertThatThrownBy(()->registry.execute(actor,org,id,op,UUID.randomUUID(),Map.of(),"INVOKE")).isInstanceOf(RestFailure.class);assertThat(peer.calls).isZero();}
 @Test void userNeedsCurrentRoleApprovalAndRevocationTakesEffect(){UUID id=register(),op=prepared(id);registry.approve(admin,org,id,op,new RestRegistry.Scope("USER",true));registry.execute(user,org,id,op,UUID.randomUUID(),Map.of(),"INVOKE");registry.approve(admin,org,id,op,new RestRegistry.Scope("USER",false));int calls=peer.calls;assertThatThrownBy(()->registry.execute(user,org,id,op,UUID.randomUUID(),Map.of(),"INVOKE")).isInstanceOf(RestFailure.class);assertThat(peer.calls).isEqualTo(calls);}
 @Test void secretsAreEncryptedWriteOnlyTenantBoundAndRestPurposeSeparated(){String secret="secret-sentinel-"+UUID.randomUUID();UUID id=(UUID)registry.register(admin,org,input(secret)).get("id"),ref=db.queryForObject("SELECT credential_id FROM app.rest_configuration WHERE connector_id=?",UUID.class,id);assertThat(credentials.resolve(org,ref).value()).isEqualTo(secret);assertThat(json.writeValueAsString(registry.detail(admin,org,id))).doesNotContain(secret,"ciphertext","nonce");assertThatThrownBy(()->credentials.resolve(other,ref)).isInstanceOf(IllegalStateException.class);db.update("INSERT INTO app.database_credential(organization_id,id,key_id,nonce,ciphertext) SELECT organization_id,id,key_id,nonce,ciphertext FROM app.rest_credential WHERE organization_id=? AND id=?",org,ref);assertThatThrownBy(()->new DatabaseCredentials(db,json,ring.toString()).resolve(org,ref)).isInstanceOf(IllegalStateException.class);registry.disable(admin,org,id,true);assertThatThrownBy(()->registry.disable(admin,org,id,false)).isInstanceOf(RestFailure.class);assertThatThrownBy(()->credentials.resolve(org,ref)).isInstanceOf(IllegalStateException.class);}
 @Test void independentlyRevokedCredentialPreventsDispatch(){UUID id=register(),op=prepared(id);UUID ref=db.queryForObject("SELECT credential_id FROM app.rest_configuration WHERE connector_id=?",UUID.class,id);credentials.revoke(org,ref);peer.calls=0;assertThatThrownBy(()->registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of(),"INVOKE")).isInstanceOf(RestFailure.class);assertThat(peer.calls).isZero();}
 @Test void runtimeAndConfigurationAuthCannotOverrideImportedContract(){UUID id=register();registry.inspect(admin,org,id);UUID health=db.queryForObject("SELECT id FROM app.rest_operation WHERE connector_id=? AND operation_key='live'",UUID.class,id);assertThatThrownBy(()->registry.approve(admin,org,id,health,new RestRegistry.Scope("INTEGRATION_ADMIN",true))).isInstanceOf(RestFailure.class);}
 @Test void argumentsAndUnknownOperationsFailBeforePeer(){UUID id=register(),op=prepared(id);peer.calls=0;for(var args:List.of(Map.of("pageSize","2"),Map.of("pageSize",51),Map.of("url","http://evil")))assertThatThrownBy(()->registry.execute(admin,org,id,op,UUID.randomUUID(),new HashMap<String,Object>(args),"INVOKE")).isInstanceOf(RestFailure.class);assertThatThrownBy(()->registry.execute(admin,org,id,UUID.randomUUID(),UUID.randomUUID(),Map.of(),"INVOKE")).isInstanceOf(RestFailure.class);assertThat(peer.calls).isZero();}
 @Test void disableAndCancelFenceLateResults()throws Exception{for(boolean disable:List.of(true,false)){UUID id=register(),op=prepared(id),execution=UUID.randomUUID();peer.block=new CountDownLatch(1);peer.entered=new CountDownLatch(1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var result=pool.submit(()->registry.execute(admin,org,id,op,execution,Map.of(),"INVOKE"));assertThat(peer.entered.await(5,TimeUnit.SECONDS)).isTrue();if(disable)registry.disable(admin,org,id,false);else registry.cancel(admin,org,id,execution);peer.block.countDown();assertThatThrownBy(()->result.get(5,TimeUnit.SECONDS)).isInstanceOf(ExecutionException.class).hasCauseInstanceOf(RestFailure.class);assertThat(db.queryForObject("SELECT status FROM app.rest_event WHERE organization_id=? AND id=?",String.class,org,execution)).isEqualTo("CANCELLED");}peer.block=null;peer.entered=null;}}
 @Test void failedAuthenticationAndRecoveryDoNotAutomaticallyApprove(){UUID id=register();registry.inspect(admin,org,id);UUID op=operation(id);registry.approve(admin,org,id,op,new RestRegistry.Scope("INTEGRATION_ADMIN",true));peer.failure="REST_AUTHENTICATION_FAILED";assertThatThrownBy(()->registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of(),"TEST")).isInstanceOf(RestFailure.class);assertThat(registry.detail(admin,org,id).get("health")).isEqualTo("AUTHENTICATION_FAILED");peer.failure=null;registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of(),"TEST");registry.activate(admin,org,id);registry.inspect(admin,org,id);assertThatThrownBy(()->registry.activate(admin,org,id)).isInstanceOf(RestFailure.class);}
 @Test void authorityRestartInterruptsIncompleteExecutionsAndRetainsGovernance(){UUID id=register(),op=prepared(id);db.update("INSERT INTO app.rest_event(organization_id,connector_id,id,actor,version,operation_id,kind,status) VALUES(?,?,?,?,1,?,'INVOKE','RUNNING')",org,id,UUID.randomUUID(),admin,op);registry=build();assertThat(db.queryForObject("SELECT count(*) FROM app.rest_event WHERE connector_id=? AND status='INTERRUPTED'",Integer.class,id)).isEqualTo(1);registry.execute(admin,org,id,op,UUID.randomUUID(),Map.of(),"INVOKE");}
 @Test void delegatedContextUsesRestAudienceAndSignature(){UUID id=register();String a=assertions.issue(admin,org,id,1,"LIST",UUID.randomUUID(),null,"");assertThat(assertions.verify(a).get("aud")).isEqualTo("ecosync-rest-gateway");assertThatThrownBy(()->assertions.verify(a.substring(0,a.length()-10)+"bad")).isInstanceOf(RestFailure.class);}
 @Test void immutableConfigurationAndOperationsCannotBeUpdatedByRuntime(){assertThat(db.queryForObject("SELECT has_table_privilege('ecosync_runtime','app.rest_configuration','UPDATE')",Boolean.class)).isFalse();assertThat(db.queryForObject("SELECT has_table_privilege('ecosync_runtime','app.rest_operation','UPDATE')",Boolean.class)).isFalse();}
 final class Peer implements RestGateway {int calls;String failure;CountDownLatch block,entered;Map<String,Object> run(){calls++;if(entered!=null)entered.countDown();if(block!=null)try{block.await(5,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}if(failure!=null)throw new RestFailure(failure);return Map.of("status",200,"data",Map.of("ok",true));}public Map<String,Object> inspect(String a,Map<String,Object> args){return run();}public Map<String,Object> call(String a,String tool,Map<String,Object> args){return run();}public List<Map<String,Object>> tools(String a){return List.of(Map.of("name","rest_invoke_operation"));}public void retire(UUID org,UUID id){}public void cancel(UUID execution){}public void reconcile(){}}
}
